import { expect, test, uniqueName } from "../../fixtures";

test.describe("Manage vendors: tenant scoping", () => {
  test(
    "a vendor from another tenant is invisible and returns vendor_not_found",
    { tag: "@VEN-07" },
    async ({ apiAs }) => {
      // Arrange: a vendor exists in tenant "Globex Procurement"
      const globexMember = await apiAs("otherTenant");
      const profileResponse = await globexMember.get("/api/me");
      expect(profileResponse.status()).toBe(200);
      expect((await profileResponse.json()).tenant.name).toBe("Globex Procurement");

      const createResponse = await globexMember.post("/api/vendors", {
        data: {
          name: uniqueName("Globex Hidden Vendor"),
          category: "software",
          contact_email: "contact@globex-vendor.test",
        },
      });
      expect(createResponse.status()).toBe(201);
      const vendorId = ((await createResponse.json()) as { id: string }).id;
      expect(vendorId).toBeTruthy();

      // The owning tenant can see it, so the 404 below is due to tenant scoping.
      const ownResponse = await globexMember.get(`/api/vendors/${vendorId}`);
      expect(ownResponse.status()).toBe(200);

      // Act: signed in as member@northwind.test, request that vendor by id
      const member = await apiAs("member");
      const response = await member.get(`/api/vendors/${vendorId}`);

      // Assert
      expect(response.status()).toBe(404);
      const body = await response.json();
      expect(body.error.code).toBe("vendor_not_found");
    },
  );
});
